-- Additive commercial configuration. Existing cards, prices and purchases are untouched.
begin;
create table public.commerce_settings(
 id text primary key check(id='global'), sales_enabled boolean not null default false,
 validation_reference text not null default '', credit_enabled boolean not null default false check(not credit_enabled),
 credit_validity_days integer not null default 7 check(credit_validity_days between 1 and 90),
 tax_percent numeric check(tax_percent between 0 and 100), variable_cost_cents integer check(variable_cost_cents>=0),
 updated_at timestamptz not null default now(), updated_by uuid references auth.users(id)
);
insert into public.commerce_settings(id) values('global');
create table public.commerce_products(
 item_id text primary key check(item_id ~ '^[a-z0-9][a-z0-9:._-]{1,139}$'),
 title text not null check(length(title) between 3 and 300), category text not null check(category in ('quick','individual','deep','free')),
 need text not null default 'organization' check(need in ('sales','attraction','brand','whatsapp','profit','organization')),
 problem text not null default '' check(length(problem)<=1000), delivery jsonb not null default '[]' check(jsonb_typeof(delivery)='array' and jsonb_array_length(delivery)<=8),
 preview text not null default '' check(length(preview)<=3000), body text not null default '' check(length(body)<=30000),
 fulfillment_kind text not null check(fulfillment_kind in ('point','bundle','document','resource')),
 target_id text not null default '' check(length(target_id)<=140),
 price_cents integer not null check(price_cents between 0 and 10000000),
 included_pro boolean not null default true, included_premium boolean not null default true,
 single_enabled boolean not null default false, active boolean not null default false, featured boolean not null default false,
 promo_enabled boolean not null default false, promo_cents integer, promo_starts_at timestamptz, promo_ends_at timestamptz,
 revision integer not null default 1 check(revision>0), updated_at timestamptz not null default now(), updated_by uuid references auth.users(id),
 check((category='free' and price_cents=0) or (category<>'free' and price_cents>=100)),
 check(not promo_enabled or (promo_cents>=100 and promo_cents<price_cents and promo_starts_at is not null and promo_ends_at>promo_starts_at))
);
create table public.commerce_product_history(
 id bigint generated always as identity primary key,item_id text not null,revision integer not null,
 snapshot jsonb not null,created_at timestamptz not null default now(),actor uuid references auth.users(id),unique(item_id,revision)
);
create function public.commerce_product_audit() returns trigger language plpgsql set search_path='' as $$
begin
 if TG_OP='UPDATE' and (new.item_id<>old.item_id or new.fulfillment_kind<>old.fulfillment_kind or new.target_id<>old.target_id) then
  raise exception 'Product identity and delivery target are immutable';
 end if;
 insert into public.commerce_product_history(item_id,revision,snapshot,actor) values(new.item_id,new.revision,to_jsonb(new),new.updated_by);
 return new;
end $$;
create trigger commerce_product_audit after insert or update on public.commerce_products for each row execute function public.commerce_product_audit();
create function public.commerce_save_product(p_actor uuid,p_product jsonb,p_revision integer) returns jsonb language plpgsql set search_path='' as $$
declare r public.commerce_products; previous public.commerce_products;
begin
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('miv-commerce:'||(p_product->>'item_id'),0));
 select * into previous from public.commerce_products where item_id=p_product->>'item_id' for update;
 if previous.item_id is not null and (previous.fulfillment_kind<>(p_product->>'fulfillment_kind') or previous.target_id<>(p_product->>'target_id')) then raise exception 'Delivery identity is immutable'; end if;
 if coalesce(previous.revision,0)<>p_revision then raise exception 'Product changed; reload before saving'; end if;
 r:=jsonb_populate_record(null::public.commerce_products,p_product||jsonb_build_object('revision',p_revision+1,'updated_by',p_actor,'updated_at',now()));
 if previous.item_id is null then insert into public.commerce_products select r.*;
 else update public.commerce_products set title=r.title,category=r.category,need=r.need,problem=r.problem,delivery=r.delivery,preview=r.preview,body=r.body,
  price_cents=r.price_cents,included_pro=r.included_pro,included_premium=r.included_premium,single_enabled=r.single_enabled,active=r.active,featured=r.featured,
  promo_enabled=r.promo_enabled,promo_cents=r.promo_cents,promo_starts_at=r.promo_starts_at,promo_ends_at=r.promo_ends_at,revision=r.revision,updated_by=r.updated_by,updated_at=r.updated_at
  where item_id=r.item_id;
 end if;
 return to_jsonb(r);
end $$;
create table public.commerce_upgrade_credits(
 id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),
 provider_payment_id text not null unique,amount_cents integer not null check(amount_cents>0),expires_at timestamptz not null,
 status text not null default 'unavailable' check(status in ('unavailable','reserved','used','revoked','expired')),
 subscription_id text unique,created_at timestamptz not null default now()
);
create table public.commerce_conversion_outbox(
 event_key text primary key,provider_payment_id text not null,event_name text not null check(event_name in ('purchase','subscription_payment')),
 value_cents integer not null check(value_cents>0),currency text not null default 'BRL' check(currency='BRL'),
 environment text not null check(environment in ('test','live','unknown')),status text not null default 'held' check(status in ('held','sent','revoked')),
 created_at timestamptz not null default now()
);
alter table public.commerce_settings enable row level security;
alter table public.commerce_products enable row level security;
alter table public.commerce_product_history enable row level security;
alter table public.commerce_upgrade_credits enable row level security;
alter table public.commerce_conversion_outbox enable row level security;
revoke all on public.commerce_settings,public.commerce_products,public.commerce_product_history,public.commerce_upgrade_credits,public.commerce_conversion_outbox from public,anon,authenticated;
grant select,insert,update on public.commerce_settings,public.commerce_products,public.commerce_product_history,public.commerce_upgrade_credits,public.commerce_conversion_outbox to service_role;
grant usage,select on sequence public.commerce_product_history_id_seq to service_role;
revoke all on function public.commerce_product_audit(),public.commerce_save_product(uuid,jsonb,integer) from public,anon,authenticated;
grant execute on function public.commerce_save_product(uuid,jsonb,integer) to service_role;

create or replace function public.diagnosis_access(p_user_id uuid,p_point_id text default null,p_consume boolean default false)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare policy public.diagnosis_rules%rowtype; plan text; used integer; free_ids jsonb; paid_ids jsonb; paid_points jsonb;
 card text; allowed boolean := false;
begin
 if p_user_id is null then raise exception 'User required'; end if;
 if p_point_id is not null then
  select card_id into card from public.diagnosis_points where point_id=p_point_id;
  if card is null then raise exception 'Unknown diagnosis point'; end if;
 end if;
 if p_consume then perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('miv-diagnosis:'||p_user_id::text,0)); end if;
 select * into strict policy from public.diagnosis_rules where id='global';
 select s.plan into plan from public.user_subscriptions s where s.user_id=p_user_id and s.status='active'
  and (s.current_period_end is null or s.current_period_end>now()) order by s.created_at desc limit 1;
 plan:=coalesce(plan,'free');
 select coalesce(jsonb_agg(point_id),'[]'::jsonb),count(*) into free_ids,used
  from public.diagnosis_unlocks where user_id=p_user_id;
 select coalesce(jsonb_agg(c.card_id),'[]'::jsonb) into paid_ids from (
  select distinct p.card_id from public.diagnosis_points p join public.user_purchases b
   on b.item_id='diagnosis:'||p.card_id and b.user_id=p_user_id and b.status='paid' and b.item_type='card'
 ) c;
 select coalesce(jsonb_agg(distinct c.target_id),'[]'::jsonb) into paid_points from public.commerce_products c
 where c.fulfillment_kind='point' and ((c.active and c.price_cents=0) or exists(select 1 from public.user_purchases p where p.user_id=p_user_id and p.item_id=c.item_id and p.item_type='card' and p.status='paid'));
 if p_point_id is not null then
  allowed:=plan in ('pro','premium') or free_ids ? p_point_id or paid_ids ? card or paid_points ? p_point_id;
  if not allowed and p_consume and used<policy.free_solution_limit then
   insert into public.diagnosis_unlocks(user_id,point_id) values(p_user_id,p_point_id) on conflict do nothing;
   select coalesce(jsonb_agg(point_id),'[]'::jsonb),count(*) into free_ids,used from public.diagnosis_unlocks where user_id=p_user_id;
   allowed:=free_ids ? p_point_id;
  end if;
 end if;
 return jsonb_build_object('allowed',allowed,'plan',plan,'free_points',free_ids,'paid_cards',paid_ids,'paid_points',paid_points,
  'free_remaining',greatest(0,policy.free_solution_limit-used),'card_price_cents',policy.card_price_cents,
  'mark_allowed',case when plan='premium' then policy.premium_mark_enabled when plan='pro' then policy.pro_mark_enabled else false end);
end;
$$;

alter table public.analytics_payments add column provider_fee_cents integer check(provider_fee_cents>=0);
create or replace function public.analytics_record_payment(p_row jsonb) returns void
language sql security invoker set search_path='' as $$
 update public.analytics_orders set environment=p_row->>'environment'
 where id=(p_row->>'order_id')::uuid and user_id=(p_row->>'user_id')::uuid
 and not exists(select 1 from public.analytics_payments p where p.provider_payment_id=p_row->>'provider_payment_id' and p.provider_updated_at>(p_row->>'provider_updated_at')::timestamptz);
 insert into public.analytics_payments(provider_payment_id,user_id,order_id,item_id,kind,status,amount_cents,refunded_cents,approved_at,created_at,provider_updated_at,environment,provider_fee_cents)
 values(p_row->>'provider_payment_id',(p_row->>'user_id')::uuid,(p_row->>'order_id')::uuid,p_row->>'item_id',p_row->>'kind',p_row->>'status',(p_row->>'amount_cents')::integer,(p_row->>'refunded_cents')::integer,(p_row->>'approved_at')::timestamptz,(p_row->>'created_at')::timestamptz,(p_row->>'provider_updated_at')::timestamptz,p_row->>'environment',(p_row->>'provider_fee_cents')::integer)
 on conflict(provider_payment_id) do update set status=excluded.status,refunded_cents=excluded.refunded_cents,
 approved_at=coalesce(excluded.approved_at,public.analytics_payments.approved_at),provider_updated_at=excluded.provider_updated_at,
 order_id=coalesce(public.analytics_payments.order_id,excluded.order_id),provenance='verified',environment=excluded.environment,provider_fee_cents=coalesce(excluded.provider_fee_cents,public.analytics_payments.provider_fee_cents)
 where excluded.provider_updated_at>=public.analytics_payments.provider_updated_at;
$$;
revoke all on function public.analytics_record_payment(jsonb) from public,anon,authenticated;
grant execute on function public.analytics_record_payment(jsonb) to service_role;

-- Keep financial conversion intent deduplicated and held until a consent-safe export is configured.
create function public.commerce_payment_update() returns trigger language plpgsql set search_path='' as $$
begin
 if new.approved_at is not null and new.amount_cents>0 then
  insert into public.commerce_conversion_outbox(event_key,provider_payment_id,event_name,value_cents,environment,status)
  values('mp:'||new.provider_payment_id,new.provider_payment_id,case when new.kind='subscription' then 'subscription_payment' else 'purchase' end,new.amount_cents,new.environment,
   case when new.refunded_cents>=new.amount_cents then 'revoked' else 'held' end)
  on conflict(event_key) do update set status=case when new.refunded_cents>=new.amount_cents then 'revoked' else public.commerce_conversion_outbox.status end;
 end if;
 if new.status in ('refunded','charged_back') or new.refunded_cents>=new.amount_cents then
  update public.user_purchases set status='refunded' where provider='mercadopago' and provider_payment_id=new.provider_payment_id and status='paid';
  update public.commerce_upgrade_credits set status='revoked' where provider_payment_id=new.provider_payment_id;
 end if;
 return new;
end $$;
create trigger commerce_payment_update after insert or update on public.analytics_payments for each row execute function public.commerce_payment_update();
create function public.commerce_purchase_guard() returns trigger language plpgsql set search_path='' as $$
declare payment public.analytics_payments;
begin
 if new.provider='mercadopago' and new.status='paid' then
  select * into payment from public.analytics_payments where provider_payment_id=new.provider_payment_id for update;
  if found and (payment.status in ('refunded','charged_back') or payment.refunded_cents>=payment.amount_cents) then raise exception 'Payment was reversed'; end if;
 end if;
 return new;
end $$;
create trigger commerce_purchase_guard before insert or update on public.user_purchases for each row execute function public.commerce_purchase_guard();
revoke all on function public.commerce_payment_update(),public.commerce_purchase_guard() from public,anon,authenticated;

alter table public.analytics_events drop constraint analytics_events_name_check;
alter table public.analytics_events add constraint analytics_events_name_check check(name in ('product_view','preview_open','page_view','card_view','card_click','card_open','favorite_add','analysis_start','analysis_complete','solution_view','report_created','tool_open','market_search','mark_open'));
create function public.commerce_metrics(p_from timestamptz,p_to timestamptz,p_environment text) returns jsonb language sql stable security invoker set search_path='' as $$
with pay as materialized(select * from public.analytics_payments where environment=p_environment and approved_at>=p_from and approved_at<p_to),
 orders as materialized(select * from public.analytics_orders where environment=p_environment and created_at>=p_from and created_at<p_to),
 summary as(select count(*) payments,count(*) filter(where kind='single') single_count,count(*) filter(where kind='subscription') subscription_count,
 coalesce(sum(amount_cents),0) gross_cents,coalesce(sum(refunded_cents),0) refunded_cents,
 coalesce(sum(amount_cents) filter(where kind='single'),0) single_gross_cents,
 coalesce(sum(amount_cents) filter(where kind='subscription'),0) subscription_gross_cents,
 case when count(*)=count(provider_fee_cents) then coalesce(sum(provider_fee_cents),0) else null end provider_fee_cents from pay),
 per_item as(select item_id,count(*) sales,sum(amount_cents-refunded_cents) revenue_cents from pay where kind='single' group by item_id),
 order_items as(select o.item_id,count(*) checkouts,count(*) filter(where exists(select 1 from public.analytics_payments p where p.order_id=o.id and p.approved_at is not null and p.refunded_cents<p.amount_cents)) converted_checkouts from orders o where kind='single' group by o.item_id)
select jsonb_build_object('scope','Período e ambiente selecionados; sem os filtros de navegação por nicho, origem ou plano.',
 'summary',(select to_jsonb(s)||jsonb_build_object('repeat_buyers',(select count(*) from (select user_id from pay where kind='single' and amount_cents>refunded_cents group by user_id having count(*)>=2)x),
 'upgraded_buyers',(select count(distinct p.user_id) from pay p where p.kind='single' and p.amount_cents>p.refunded_cents and exists(select 1 from public.analytics_payments sub where sub.user_id=p.user_id and sub.kind='subscription' and sub.environment=p_environment and sub.approved_at>p.approved_at and sub.approved_at<p_to and sub.amount_cents>sub.refunded_cents)),
 'estimated_contribution_cents',case when s.provider_fee_cents is not null and c.tax_percent is not null and c.variable_cost_cents is not null then round((s.gross_cents-s.refunded_cents)*(1-c.tax_percent/100)-s.provider_fee_cents-s.payments*c.variable_cost_cents) else null end,
 'tax_percent',c.tax_percent,'variable_cost_cents',c.variable_cost_cents) from summary s cross join public.commerce_settings c where c.id='global'),
 'cards',coalesce((select jsonb_agg(to_jsonb(x)) from (select coalesce(s.item_id,o.item_id) item_id,coalesce(s.sales,0) sales,coalesce(s.revenue_cents,0) revenue_cents,coalesce(o.checkouts,0) checkouts,coalesce(o.converted_checkouts,0) converted_checkouts from per_item s full join order_items o using(item_id) order by coalesce(s.sales,0) desc limit 100)x),'[]'::jsonb),
 'held_conversions',(select count(*) from public.commerce_conversion_outbox where environment=p_environment and status='held' and created_at>=p_from and created_at<p_to))
$$;
revoke all on function public.commerce_metrics(timestamptz,timestamptz,text) from public,anon,authenticated;
grant execute on function public.commerce_metrics(timestamptz,timestamptz,text) to service_role;


